using System;
using System.Linq;
using System.Reflection;
using UnityEngine;
namespace BWVR.Editor {
public static class LightningChecks {
 static readonly BindingFlags F=BindingFlags.Instance|BindingFlags.NonPublic;
 static void Check(bool ok,string why){if(!ok)throw new Exception(why);}
 public static void Verify(Action<PlayImpactTarget,string> capture=null){
  Check(Application.isPlaying,"Enter Play mode");var slice=UnityEngine.Object.FindAnyObjectByType<QuestSlice>();var god=slice.GetComponentInChildren<CreatureHybrid>();var weather=slice.GetComponentInChildren<IslandWeather>();var palette=slice.GetComponentInChildren<GodToolPalette>();var brush=palette.Brush;var miracles=slice.GetComponentInChildren<DivineIntervention>();var nav=slice.GetComponent<IslandNavigation>();var field=typeof(QuestSlice).GetField("state",F);var original=(SliceState)field.GetValue(slice);bool automatic=weather.automatic,unlimited=miracles.tuning.unlimitedEnergy;var state=new SliceState{developmentFocus=true};
  god.Interrupt("Lightning QA");field.SetValue(slice,state);state.Hybrid.time=100;state.Hybrid.energy=100;weather.automatic=false;miracles.tuning.unlimitedEnergy=false;weather.ResetWorld();
  var targets=weather.Targets.Where(t=>weather.PlayerLightningTarget(t)&&t.kind=="tree"&&nav.Terrain.Dry(t.transform.position)).Take(2).ToArray();
  try{
   Check(targets.Length==2,"No standing test targets");var tree=targets[0];var wet=targets[1];
   Check(brush.CanLightning(tree,out _)&&state.weather.materials.Length==0&&state.Hybrid.energy==100,"Target preview mutated heat or energy");
   Check(!brush.ProcessLightning(tree,true,.02f),"Charge cast immediately");state.Hybrid.time+=.3f;Check(!brush.ProcessLightning(tree,false,.02f)&&state.Hybrid.energy==100&&state.Weather.Find(tree.id)==null,"Short tap cast or charged energy");
   brush.ProcessLightning(tree,true,.02f);state.Hybrid.time+=1.3f;Check(brush.LightningCharge==1,"Charge did not follow simulation time");brush.ProcessLightning(wet,true,.02f);Check(brush.LightningCharge==0&&!brush.ProcessLightning(wet,false,.02f),"Retarget transferred full charge");
   brush.ProcessLightning(tree,true,.02f);state.Hybrid.time+=.5f;state.paused=true;Check(!brush.ProcessLightning(tree,true,.02f)&&!brush.Active&&brush.LightningCharge==0,"Pause retained charge");state.paused=false;Check(!brush.ProcessLightning(tree,false,.02f),"Resume released an old cast");
   brush.ProcessLightning(tree,true,.02f);state.Hybrid.time+=1.3f;brush.ProcessLightning(tree,true,.02f);capture?.Invoke(tree,"charged");Check(brush.ProcessLightning(tree,false,.02f)&&state.Weather.Find(tree.id)?.burning==true&&state.Hybrid.energy==80,"Charged dry strike did not ignite/pay once");capture?.Invoke(tree,"strike");int pulses=brush.Pulses;Check(!brush.ProcessLightning(tree,false,.02f)&&brush.Pulses==pulses&&state.Hybrid.energy==80,"Duplicate release cast twice");Check(!brush.CanLightning(wet,out _),"Cooldown bypassed");
   weather.Advance(1,false);Check(state.Weather.Find(tree.id).fuel<1&&state.WorldPlay.Damage(tree.id)>0,"Lightning did not enter the real heat/fuel/damage system");
   var ground=nav.Terrain.Project(tree.transform.position);miracles.tuning.unlimitedEnergy=true;for(int i=0;i<20&&state.Weather.Find(tree.id)?.burning==true;i++){state.Hybrid.time+=.6f;Check(brush.RainPulse(ground),"Rain brush did not reach lightning fire");}Check(state.Weather.Find(tree.id)?.burning==false,"Rain could not extinguish lightning fire");capture?.Invoke(tree,"doused");
   state.Hybrid.time+=4;state.Weather.Touch(wet.id).wetness=1;brush.ProcessLightning(wet,true,.02f);state.Hybrid.time+=1.3f;Check(brush.ProcessLightning(wet,false,.02f)&&state.Weather.Find(wet.id).heat>0&&!state.Weather.Find(wet.id).burning,"Wet material rules bypassed");
   state.Hybrid.time+=4;miracles.tuning.unlimitedEnergy=false;state.Hybrid.energy=19;Check(!brush.CanLightning(wet,out _),"Unaffordable charge accepted");miracles.tuning.unlimitedEnergy=true;state.Hybrid.energy=0;brush.ProcessLightning(wet,true,.02f);state.Hybrid.time+=1.3f;Check(brush.ProcessLightning(wet,false,.02f)&&state.Hybrid.energy==0,"Unlimited testing failed at zero energy");
   Check(!brush.CanLightning(weather.Targets.First(t=>t.villager!=null),out _),"Actor treated as scenery target");var impostor=new GameObject("QA unregistered lightning target");try{var fake=impostor.AddComponent<PlayImpactTarget>();fake.id=tree.id;fake.kind="tree";Check(!brush.CanLightning(fake,out _),"Unregistered target accepted");}finally{UnityEngine.Object.DestroyImmediate(impostor);}
   state.Hybrid.time+=4;palette.Select(SpiritualTool.Lightning);var bounds=wet.Bounds(nav.Scale);var ray=new Ray(bounds.center+Vector3.up*(bounds.extents.y+.1f),Vector3.down);palette.Process(ray,true,true,false,.02f,false);Check(!brush.Active,"Selection click leaked into charge");palette.Process(ray,false,true,false,.02f,false);palette.Process(ray,true,true,false,.02f,false);Check(brush.Active&&palette.PreviewValid,"Pointer failed to acquire scenery target");state.Hybrid.time+=1.3f;palette.Process(ray,true,false,false,.02f,true);Check(!brush.Active&&!palette.Selected.HasValue&&!brush.ProcessLightning(wet,false,.02f),"Tracking loss retained a charged strike");
   state.Hybrid.time+=4;palette.Select(SpiritualTool.Lightning);palette.Process(ray,false,true,false,.02f,false);palette.Process(ray,true,true,false,.02f,false);state.Hybrid.time+=1.3f;pulses=brush.Pulses;palette.Process(ray,false,true,false,.02f,false);Check(brush.Pulses==pulses+1&&!brush.Active,"Controller release did not cast once");palette.Process(ray,false,true,false,.02f,false);Check(brush.Pulses==pulses+1,"Controller release repeated cast");palette.Cancel();
   state.Hybrid.time+=4;brush.ProcessLightning(wet,true,.02f);state.Hybrid.time+=9;brush.ProcessLightning(wet,true,.02f);Check(!brush.Active&&!brush.ProcessLightning(wet,false,.02f),"Timed-out charge fired");
   Check(state.Hybrid.Evidence.events.Any(e=>e.source==EvidenceSource.PlayerMiracle&&e.outcome.StartsWith("Player lightning:"))&&!state.Hybrid.receipt.eligible&&state.Valid(),"Lightning misattribution or invalid state");
   brush.ProcessLightning(wet,true,.02f);state.Hybrid.time+=.6f;Check(brush.Active&&brush.LightningCharge>0,"No in-flight charge for reload test");typeof(QuestSlice).GetMethod("Save",F).Invoke(slice,null);typeof(QuestSlice).GetMethod("Load",F).Invoke(slice,null);var loaded=(SliceState)field.GetValue(slice);Check(loaded.Valid()&&loaded.Weather.Find(wet.id).wetness==1&&loaded.Hybrid.Evidence.events.Any(e=>e.outcome.StartsWith("Player lightning:")),"Native Save/Load lost lightning consequences");Check(brush.CanLightning(wet,out _)&&brush.LightningCharge==0,"Reload retained charge");
   Debug.Log("BWVR_LIGHTNING_PASS: simulation-time charge/release, short tap/retarget/pause/duplicate/cooldown/timeout/tracking protection, dry ignition, native fuel/damage, rain extinguishing, wet resistance, costs/unlimited energy, target registry, player attribution and native Save/Load");
  }finally{palette.Cancel();brush.Stop();field.SetValue(slice,original);weather.automatic=automatic;miracles.tuning.unlimitedEnergy=unlimited;foreach(var target in weather.Targets)target.Apply(original.worldPlay?.Damage(target.id)??0);weather.ResetWorld();god.NewSeason();}
 }
}
}
